import  express from "express";
import "express-async-errors";
import errorMiddleware from "./middleware/errorMiddleware";

import dotenv from "dotenv";
import LoginRouter from './router/user.router';
import ProductsRouter from './router/product.router';
import CarrinhoRouter from './router/carrinho.router';
import OrdersRouter from './router/orders.router';

dotenv.config();

class App {
  public app: express.Express;

  constructor() {
    this.app = express();

    this.config();

    // Não remover essa rota
    this.app.get("/", (req, res) => res.json({ ok: true }));

    // Login
    this.app.use(LoginRouter)

    //  Produtos
    this.app.use(ProductsRouter)

    // Carrinho
    this.app.use(CarrinhoRouter)

    // Pedidos
    this.app.use(OrdersRouter);

    // Não remova esse middleware de erro, mas fique a vontade para customizá-lo
    // Mantenha ele sempre como o último middleware a ser chamado
    this.app.use(errorMiddleware);
  }

  private config(): void {
    const accessControl: express.RequestHandler = (_req, res, next) => {
      res.header("Access-Control-Allow-Origin", "*");
      res.header(
        "Access-Control-Allow-Methods",
        "GET,POST,DELETE,OPTIONS,PUT,PATCH"
      );
      res.header("Access-Control-Allow-Headers", "*");
      next();
    };

    this.app.use(express.json());
    this.app.use(accessControl);
  }

  public start(PORT: string | number): void {
    this.app.listen(PORT, () => console.log(`Running on port ${PORT}`));
  }
}

export { App };

export const { app } = new App();

import { Request, Response, NextFunction } from 'express';
import ICustomError from '../Interfaces/erroMiddleware';

function errorMiddleware(error: ICustomError, _req: Request, res: Response, _next: NextFunction) {
  const status = error.statusCode || 500;
  const message = error.message || 'Something went wrong';

  console.log(error);
  return res.status(status).json({ message });
}

export default errorMiddleware;

import { Router } from "express";
import {
  Login,
  registreUsers,
  updateUserController,
  getUserLoginController,
  tokenValidate,
} from "../controllers/users.controller";
import { erroLogin, erroCreateUser } from '../middleware/erroLogin,middleware';

const LoginRouter = Router();

LoginRouter.post("/login", erroLogin, Login);
LoginRouter.put("/login", updateUserController);
LoginRouter.get("/login", getUserLoginController);
LoginRouter.get('/verifyToken', tokenValidate)
LoginRouter.post("/register", erroCreateUser, registreUsers);

export default LoginRouter;

import loginService from "./../services/users.services";
import { Request, Response } from "express";

const Login = async (req: Request, res: Response): Promise<void> => {
  const { email, password } = req.body;
  const userlogin = { email, password };
  const { status, data } = await loginService.login(userlogin);
  res.status(status).json(data);
};


// controller
const registreUsers = async (req: Request, res: Response) => {
  const { name, lastname, email, password, tumrbl, endereco, cep, telefone } =
    req.body;

  // Validação de dados
  if (!name || !lastname || !email || !password) {
    return res
      .status(400)
      .json({ message: "Por favor, forneça todos os campos necessários." });
  }

  // Criação de novo usuário
  const newUser = await loginService.registerUser({
    name,
    lastname,
    email,
    password,
    tumrbl,
    endereco,
    cep,
    telefone,
  });

  // Retorno de sucesso
  return res.status(201).json(newUser);
};

const updateUserController = async (req: Request, res: Response) => {
  const authorizationHeader = req.get("Authorization");
  const dataUser = req.body;
  if (!authorizationHeader) {
    return res.status(401).json({ message: "Token not found" });
  }
  const token = authorizationHeader.split(" ")[1];
  const serviceupdate = await loginService.updateUser(dataUser, token);
  return res.status(200).json(serviceupdate);
};

const getUser = async (req: Request, res: Response) => {
  const user = await loginService.getallUser();
  return res.status(200).send(user);
};

const getUserLoginController = async (req: Request, res: Response) => {
  const authorizationHeader = req.get("Authorization");
  if (!authorizationHeader) {
    return res.status(401).json({ message: "Token not found" });
  }
  const token = authorizationHeader.split(" ")[1];
  const { status, data } = await loginService.getUserLogin(token);
  return res.status(status).json(data);
};

const tokenValidate = (req: Request, res: Response) => {
  const authorizationHeader = req.get("Authorization");
  if (!authorizationHeader) return res.status(401).json({ message: "Token not found" });
  const isTokenValid = loginService.validateToken(authorizationHeader);
  return res.status(200).json(isTokenValid)
};

export {
  Login,
  registreUsers,
  getUser,
  updateUserController,
  getUserLoginController,
  tokenValidate,
};

import * as bcrypt from "bcryptjs";
import UserModels from "../database/models/User.models";
import { Ilogin, createUser, updateUser } from "../Interfaces/IUsers";
import { verifyToken, sign } from "../utils/token.utils";

const SALT_ROUNDS = process.env.BCRYPT_SALT_ROUNDS || 10;

const login = async (user: Ilogin) => {
  const { email, password } = user;

  if(!email || !password) {
     return {
       status: 401,
       data: { message: "Email and Password are required" },
     };
  }

  const verifyLogin = await UserModels.findOne({ where: { email } });
  if (!verifyLogin || !verifyLogin.dataValues) {
    return { status: 401, data: { message: "Invalid email or password" } };
  }
  const verfifyPassword = await bcrypt.compare(password, verifyLogin.password);
  if (!verfifyPassword) {
    return { status: 401, data: { message: "Invalid email or password" } };
  }
  const { role, id } = verifyLogin;
  const token = sign({ id, email, role });
  return { status: 200, data: { token } };
};

const registerUser = async (userData: createUser) => {
  const { name, lastname, email, password, tumrbl, endereco, cep, telefone } =
    userData;
  const username = `${name} ${lastname}`;
  const bcryptPassword = bcrypt.hashSync(password, SALT_ROUNDS);
  const newUser = await UserModels.create({
    username,
    email,
    tumrbl: tumrbl || "",
    password: bcryptPassword,
    role: "USER",
    endereco,
    cep,
    telefone,
  });
  return newUser;
};

const updateUser = async (userUpdate: updateUser, token: string) => {
  let { ...dataUpdate } = userUpdate;
  const tokenPayload = verifyToken(token);

  if (!tokenPayload) {
    throw new Error("Invalid token");
  }
  const { id } = tokenPayload;
  const user = await UserModels.findOne({ where: { id } });

  if (!user) {
    throw new Error("User not found");
  }

  if (dataUpdate.password) {
    dataUpdate.password = bcrypt.hashSync(dataUpdate.password, SALT_ROUNDS);
  }
  const updateUser = await UserModels.update(dataUpdate, { where: { id } });
  return updateUser;
};

const getallUser = async () => {
  const user = await UserModels.findAll();
  return user;
};

const getUserLogin = async (token: string) => {
  const tokenPayload = verifyToken(token);
  if (!tokenPayload) {
    return { status: 401, data: { message: "token invalido" } };
  }
  const { id } = tokenPayload;
  const user = await UserModels.findByPk(id, {
    attributes: { exclude: ["password"] },
  });
  return { status: 200, data: user };
};

const validateToken = (token: string) => {
  if (token) false;
  const isToken = verifyToken(token);
  if (!isToken) false;
  return true;
};

export default {
  login,
  registerUser,
  getallUser,
  updateUser,
  getUserLogin,
  validateToken,
};

import * as jwt from 'jsonwebtoken';

const secret = process.env.JWT_SECRET || 'vingador mais forte';

type TokenPayload = {
  id:number;
  email: string;
  role: string;
};

// criando token
function sign(payload: TokenPayload): string | null {
  try {
    const token = jwt.sign(payload, secret);
    return token;
  } catch (erro) {
    console.log('Erro na geracao do token', erro);
    return null;
  }
}

// validando token
function verifyToken(token: string): TokenPayload | null {
  try {
    const tokenVerify = jwt.verify(token, secret) as TokenPayload;
    return tokenVerify;
  } catch (err) {
    return null;
  }
}



export { sign, verifyToken };

import { NextFunction, Request, Response } from "express";
import Users from "../database/models/User.models";

const erroLogin = (req: Request, res: Response, next: NextFunction) => {
  const { email, password } = req.body;
  if (!email || !password) {
    return res.status(401).json({ message: "Email and Password are required" });
  }
  next();
};

const erroCreateUser = async (
  req: Request,
  res: Response,
  next: NextFunction
) => {
  const { email, name, lastname, password } = req.body;

  if (!email || !name || !lastname || !password) {
    return res.status(400).json({message: "All fields are necessary."});
  }

  const username = `${name} ${lastname}`;
  const userEmail = await Users.findOne({ where: { email } });
  const usernames = await Users.findOne({ where: { username } });
  if (usernames || userEmail) {
    return res.status(409).json({ message: "This User already exists." });
  }
  next();
};

export { erroLogin, erroCreateUser };

