import Products from "../database/models/Produtos.models";
import Categorias from "../database/models/Categoria.models";
import Marcas from "../database/models/Marcas.models";
import Cores from "../database/models/Cores.models";

const getAllProducts = async () => {
  const allProducts = await Products.findAll({
    include: [
      {
        model: Categorias,
        as: "categoria",
        attributes: ["categName"],
      },
      {
        model: Marcas,
        as: "marca",
        attributes: ["brandName"],
      },
      {
        model: Cores,
        as: "color",
        attributes: ["colorName"],
      },
    ],
    attributes: {
      exclude: ["colorsId", "categoriesId", "brandsId"],
    },
  });


const formattedProducts = allProducts.map((product: any) => ({
  ...product.toJSON(),
  categoria: product.categoria?.categName,
  marca: product.marca?.brandName,
  color: product.color?.colorName,
}));

  return { status: 200, data: formattedProducts };
};

const ProductByIdServices = async (id: number) => {
  if(!id) {
    return { status: 400, message: "Id is required" }
  }
  const getProduct = await Products.findByPk(id, {
    include: [
      {
        model: Categorias,
        as: "categoria",
        attributes: ["categName"],
      },
      {
        model: Marcas,
        as: "marca",
        attributes: ["brandName"],
      },
      {
        model: Cores,
        as: "color",
        attributes: ["colorName"],
      },
    ],
    attributes: {
      exclude: ["colorsId", "categoriesId", "brandsId"],
    },
  });

  if(!getProduct) {
    return { status: 404, data: "Produto não encontrado" };
  }

 const { marca, categoria, color, ...rest } = getProduct.toJSON() as any;


  const data = {
    ...rest, 
    brandName: marca?.brandName,
    catgName: categoria?.categName,
    colorName: color?.colorName,
  }

  return { status: 200, data: data };
};

interface IaddProduct {
  productName: string;
  description: string;
  price: number;
  gender: string;
  promo?: number;
  categories: string;
  brands: string;
  colors: string;
  images: string[];
  thumbnail: string;
  quantity: number;
}

const addProduct = async (param: IaddProduct) => {
  const existingProduct = await Products.findOne({
    where: { productName: param.productName },
  });

  if (existingProduct) {
    return { status: 409, data: null, message: "Produto já existe." };
  }

  let category = await Categorias.findOne({
    where: { categName: param.categories },
  });

  if (!category) {
    category = await Categorias.create({
      categName: param.categories,
    });
  }

  let marca = await Marcas.findOne({ where: { brandName: param.brands } });

  if (!marca) {
    marca = await Marcas.create({
      brandName: param.brands,
    });
  }

  let cor = await Cores.findOne({ where: { colorName: param.colors } });

  if (!cor) {
    cor = await Cores.create({
      colorName: param.colors,
    });
  }

  const product = await Products.create({
    productName: param.productName,
    description: param.description,
    price: param.price,
    promo: param.promo || 0,
    gender: param.gender,
    categoriesId: category.id,
    brandsId: marca.id,
    colorsId: cor.id,
    images: param.images,
    thumbnail: param.thumbnail,
    quantity: param.quantity,
  });

  return { status: 201, data: product };
};

interface UpdateData {
  productName?: string;
  descricao?: string;
  preco?: number;
  promo?: number;
  genero?: string;
  color?: { colorName: string };
  categoria?: { categName: string };
  marca?: { brandName: string };
  imagens?: string[];
}

const updateProduct = async (
  id: number,
  updateData: UpdateData
): Promise<{ status: number; data: any }> => {
  const product = await Products.findByPk(id);
  console.log(product);

  if (!product) {
    return { status: 404, data: { message: "Produto não encontrado." } };
  }

  try {
    await product.update(updateData);

    return {
      status: 200,
      data: { updateData },
    };
  } catch (error: any) {
    return {
      status: 500,
      data: { message: "Erro ao atualizar o produto.", error: error.message },
    };
  }
};

export default { getAllProducts, addProduct, updateProduct, ProductByIdServices };

import { Router } from "express";
import {
  getProductFromCart,
  addProductToCart,
  updateCar,
} from "../controllers/Carrinho.controller";

const CarrinhoRouter = Router();

CarrinhoRouter.get("/carrinho", getProductFromCart);
CarrinhoRouter.post("/carrinho", addProductToCart);
CarrinhoRouter.put("/carrinho", updateCar);

export default CarrinhoRouter;

import { IProducts } from "./../Interfaces/IProduct";
import {
  getProductsInCartService,
  addProductToCartService,
  updatequantityProductCar,
} from "../services/Carrinho.services";
import { Request, Response } from "express";

const getProductFromCart = async (req: Request, res: Response) => {
  const authorizationHeader = req.get("Authorization");
  if (!authorizationHeader) {
    return res.status(401).json({ message: "Token not found" });
  }
  const token = authorizationHeader.split(" ")[1];
  const resultProductCar = await getProductsInCartService(token);
  const { status, data } = resultProductCar;
  res.status(status).json(data);
};

const addProductToCart = async (req: Request, res: Response) => {
  const authorizationHeader = req.get("Authorization");
  if (!authorizationHeader) {
    return res.status(401).json({ message: "Token not found" });
  }
  const token = authorizationHeader.split(" ")[1];
  const { productId, quantidade } = req.body;
  const resultProductCar = await addProductToCartService(
    token,
    productId,
    quantidade
  );
  const { status, data } = resultProductCar;
  res.status(status).json(data);
};

const updateCar =async (req: Request, res: Response) => {
  const { IProduct, operador, number } = req.body;
  if(!IProduct ) {
    return res
      .status(400)
      .json({
        message: `IProduct are required  ${IProduct}`,
      });
  }
  const { status, data } = await updatequantityProductCar(
    IProduct,
    operador,
    number
  );
  return res.status(status).json(data);
};

export { getProductFromCart, addProductToCart, updateCar };

import Carrinho from "../database/models/ShoppingCart.models";
import { verifyToken } from "../utils/token.utils";
import Products from "../database/models/Produtos.models";
import Users from "../database/models/User.models";

const getProductsInCartService = async (token: string) => {
  const tokenId = verifyToken(token);
  if (!tokenId) {
    throw new Error("Token inválido");
  }
  const { id } = tokenId;
  const carrinho = await Carrinho.findAll({
    where: { userId: id },
    include: [
      {
        model: Products,
        as: "product",
        attributes: ["productName", "price", "images"],
      },
    ],
  });
  return { status: 200, data: carrinho };
};

const addProductToCartService = async (
  token: string,
  product: number,
  quantidade: number
) => {
  const tokenId = verifyToken(token);
  if (!tokenId) {
    throw new Error("Invalid token");
  }

  const { id } = tokenId;
  const createCar = await Carrinho.create({
    userId: id,
    idProduct: product,
    quantidade,
  });

  return { status: 201, data: createCar };
};

const removeItemCar = async (idProduct: number) => {
  await Carrinho.destroy({ where: { idProduct } });
  return { status: 201, data: { message: "item removido" } };
};

const updatequantityProductCar = async (
  idProduct: number,
  operador: boolean,
  number: number
) => {
  const carItem = await Carrinho.findOne({ where: { idProduct } });

  if (!carItem) {
    return { status: 201, data: { message: "item não encontrado" } };
  }

  if (!operador && carItem.quantidade <= 0) {
    removeItemCar(idProduct);
    return { status: 401, data: { message: "Produto vazio" } };
  }

  let updateCar;
  if (!operador) {
     updateCar = await carItem.update({
      quantidade: carItem.quantidade - number,
    });
  }
  updateCar = await carItem.update({
    quantidade: carItem.quantidade + number,
  });


  return { status: 201, data: updateCar };
};

export {
  getProductsInCartService,
  addProductToCartService,
  updatequantityProductCar,
};

